<template><div><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb16" /><el-form :inline="true"><el-form-item :label="bilingual('规则类型','Rule type')"><el-select v-model="kind" style="width:240px"><el-option v-for="item in definitions" :key="item.kind" :label="label(item)" :value="item.kind" /></el-select></el-form-item><el-form-item v-if="kind!=='invoiceTypes'" :label="bilingual('客户','Client')"><el-select v-model="query.client" clearable filterable remote :remote-method="q=>lookup('clients',q)" style="width:230px"><el-option v-for="item in options.clients||[]" :key="item.id" :label="item.label" :value="item.id" /></el-select></el-form-item><el-form-item><el-button type="primary" icon="Search" :loading="loading" @click="search">{{ bilingual('搜索','Search') }}</el-button><el-button v-if="canEdit" icon="Plus" :disabled="blocked" @click="edit()">{{ bilingual('新增','Add') }}</el-button></el-form-item></el-form>
<el-table :data="rows" v-loading="loading" border row-key="id"><el-table-column v-for="item in definition.fields" :key="item.key" :label="label(item)" min-width="150" show-overflow-tooltip><template #default="scope">{{ display(scope.row[item.key],item) }}</template></el-table-column><el-table-column v-if="kind.endsWith('Tiers')" :label="bilingual('阶梯起点与单价','Tier starts and rates')" min-width="220"><template #default="scope">{{(scope.row.tiers||[]).map(t=>t.from+' → '+t.rate).join('; ')}}</template></el-table-column><el-table-column :label="bilingual('操作','Actions')" width="155" fixed="right"><template #default="scope"><el-button link type="primary" :disabled="blocked" @click="edit(scope.row)">{{canEdit?bilingual('编辑','Edit'):bilingual('查看','View')}}</el-button><el-button v-if="canEdit" link type="danger" :disabled="blocked" @click="remove(scope.row)">{{bilingual('删除','Delete')}}</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load" />
<el-drawer v-model="opened" :title="label(definition)" size="min(720px,100%)" :close-on-click-modal="!saving" :close-on-press-escape="!saving" :show-close="!saving"><el-alert v-if="formError" :title="formError" type="error" :closable="false" class="mb16" /><el-alert v-if="kind==='orderTiers'" type="info" :closable="false" :title="bilingual('订单量阶梯按订单数结算。每段起点包含在该段内，首段从1开始。','Order volume tiers use order counts. Each start is inclusive; the first tier begins at 1.')" class="mb16" /><el-form ref="formRef" :model="form" label-position="top" :disabled="!canEdit||blocked"><el-row :gutter="20"><el-col v-for="item in definition.fields" :key="item.key" :xs="24" :sm="item.type==='textarea'?24:12"><el-form-item :label="label(item)" :prop="item.key" :rules="item.required?[{required:true,message:bilingual('请填写此项','Complete this field'),trigger:['blur','change']}]:[]"><el-select v-if="item.type==='ref'||item.type==='refName'" v-model="form[item.key]" clearable filterable remote :remote-method="q=>lookup(item.source,q)" style="width:100%"><el-option v-for="option in withCurrent(item.source,form[item.key],item.type)" :key="option.id" :label="option.label" :value="item.type==='refName'?option.label:option.id" /></el-select><el-select v-else-if="item.type==='select'" v-model="form[item.key]" style="width:100%"><el-option v-for="option in item.options" :key="option" :label="financeOption(option)" :value="option" /></el-select><el-switch v-else-if="item.type==='toggle'" v-model="form[item.key]" /><el-input v-else-if="item.type==='decimal'" v-model="form[item.key]" inputmode="decimal" :aria-label="label(item)" maxlength="35" /><el-input v-else v-model="form[item.key]" :type="item.type==='textarea'?'textarea':'text'" :maxlength="item.key==='notes'?5000:item.key==='description'?500:100" /></el-form-item></el-col></el-row><template v-if="kind.endsWith('Tiers')"><h3>{{bilingual('价格阶梯','Pricing tiers')}}</h3><div v-for="(tier,index) in form.tiers" :key="index" class="tier-row"><el-form-item :label="bilingual('起始数量','From quantity')"><el-input-number v-model="tier.from" :min="1" :precision="0" controls-position="right" /></el-form-item><el-form-item :label="bilingual('单价','Rate')"><el-input v-model="tier.rate" inputmode="decimal" maxlength="35" /></el-form-item><el-button icon="Delete" :aria-label="bilingual('删除阶梯','Remove tier')" :disabled="form.tiers.length===1" @click="form.tiers.splice(index,1)" /></div><el-button icon="Plus" :disabled="form.tiers.length>=100" @click="form.tiers.push({from:(form.tiers.at(-1)?.from||0)+1,rate:0})">{{bilingual('新增阶梯','Add tier')}}</el-button></template></el-form><template #footer><el-button :disabled="saving" @click="opened=false">{{bilingual('关闭','Close')}}</el-button><el-button v-if="canEdit" type="primary" :loading="saving" :disabled="blocked" @click="save">{{bilingual('保存','Save')}}</el-button></template></el-drawer></div></template>
<script setup>
import {computed,reactive,ref,watch,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
import auth from '@/plugins/auth'
import useUserStore from '@/store/modules/user'
import {bilingual,financeOption} from '@/warehouse/i18n'
import {getWarehouseLookups} from '@/api/warehouse'
import {financeRuleKinds,financeRulePayload,financePending,financePendingError,financeBusy,financeRevision,submitFinance} from '@/warehouse/finance'
const user=useUserStore(),definitions=computed(()=>financeRuleKinds.filter(item=>!item.admin||Number(user.id)===1)),kind=ref('orderTiers'),definition=computed(()=>definitions.value.find(item=>item.kind===kind.value)),canEdit=computed(()=>auth.hasPermi('warehouse:finance:edit')),blocked=computed(()=>saving.value||financeBusy.value||!!financePending.value||!!financePendingError.value)
const query=reactive({pageNum:1,pageSize:20,client:''}),rows=ref([]),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),formError=ref(''),opened=ref(false),form=ref({}),formRef=ref(),record=ref(null),options=reactive({}),tickets=new Map()
const label=item=>bilingual(item?.label,item?.labelEn),display=(value,item)=>value===null||value===undefined||value===''?'—':item.type==='ref'?(options[item.source]?.find(option=>option.id===value)?.label||value):item.type==='select'?financeOption(value):typeof value==='boolean'?(value?bilingual('是','Yes'):bilingual('否','No')):value
const withCurrent=(source,id,type)=>id&&!options[source]?.some(item=>(type==='refName'?item.label:item.id)===id)?[{id,label:String(id)},...(options[source]||[])]:options[source]||[]
async function lookup(source,q=''){if(source==='channels'&&!auth.hasPermi('warehouse:channels:list')){options.channels=[{id:'manual',label:'Manual'}];return;}const ticket=(tickets.get(source)||0)+1;tickets.set(source,ticket);try{const result=await getWarehouseLookups(source,q,source==='products'&&form.value.client?{client:form.value.client}:{});if(tickets.get(source)===ticket)options[source]=source==='channels'?[{id:'manual',label:'Manual'},...result.data.filter(row=>row.active!==false)]:result.data}catch(e){error.value=e.message}}
let generation=0,assigning=false
async function load(){const ticket=++generation,target=kind.value;loading.value=true;error.value='';try{const result=await request({url:'/warehouse/finance/rules/'+target,method:'get',params:{...query,...(target==='invoiceTypes'?{client:''}:{})}});if(ticket===generation){rows.value=result.rows;total.value=result.total}}catch(e){if(ticket===generation)error.value=e.message}finally{if(ticket===generation)loading.value=false}}
function search(){query.pageNum=1;load()}
async function edit(row){if(blocked.value)return;const target=kind.value;formError.value='';try{const value=row?(await request({url:'/warehouse/finance/rules/'+target+'/'+encodeURIComponent(row.id),method:'get'})).data:null;if(target!==kind.value)return;record.value=value;const next={};for(const item of definition.value.fields)next[item.key]=value&&Object.hasOwn(value,item.key)?value[item.key]:Object.hasOwn(item,'default')?item.default:item.type==='decimal'?undefined:'';if(target.endsWith('Tiers'))next.tiers=value?.tiers?value.tiers.map(item=>({...item})):[{from:1,rate:0}];assigning=true;form.value=next;assigning=false;opened.value=true;for(const source of new Set(definition.value.fields.filter(item=>item.source).map(item=>item.source)))lookup(source)}catch(e){formError.value=e.message}}
async function save(){if(blocked.value||!canEdit.value)return;saving.value=true;formError.value='';try{if(!await formRef.value.validate().catch(()=>false))return;const payload=financeRulePayload(definition.value,form.value,record.value?._version,crypto.randomUUID());if(record.value&&!Number.isInteger(payload._version))throw Error(bilingual('请重新读取规则版本','Reload the rule version'));await submitFinance({label:label(definition.value),url:'/warehouse/finance/rules/'+kind.value+(record.value?'/'+encodeURIComponent(record.value.id):''),method:record.value?'put':'post',data:payload});opened.value=false;ElMessage.success(bilingual('规则已保存','Rule saved'))}catch(e){formError.value=e.message==='invalid_tiers'?bilingual('阶梯必须从1开始，起点不能重复；最多100段。','Tiers must start at 1 with unique integer starts and at most 100 tiers.'):e.message==='invalid_decimal'?bilingual('金额或数量须为非负十进制数，最多9位小数；税率不能超过100%。','Use non-negative decimals with at most 9 decimal places. VAT must not exceed 100%.'):e.message}finally{saving.value=false}}
async function remove(row){if(blocked.value||!canEdit.value)return;saving.value=true;try{try{await ElMessageBox.confirm(bilingual('确认删除此规则？已记录的费用快照不会被改写。','Delete this rule? Existing recorded charge snapshots remain unchanged.'),bilingual('删除规则','Delete rule'),{type:'warning',confirmButtonText:bilingual('删除','Delete'),cancelButtonText:bilingual('取消','Cancel')})}catch{return}if(!Number.isInteger(row._version))throw Error(bilingual('缺少版本，请刷新','Version missing. Refresh first.'));await submitFinance({label:bilingual('删除规则','Delete rule'),url:'/warehouse/finance/rules/'+kind.value+'/'+encodeURIComponent(row.id),method:'delete',params:{version:row._version,requestId:crypto.randomUUID()}});ElMessage.success(bilingual('规则已删除','Rule deleted'))}catch(e){error.value=e.message}finally{saving.value=false}}
watch(kind,()=>{opened.value=false;query.pageNum=1;load()});watch(()=>form.value.client,()=>{if(!assigning&&opened.value&&kind.value==='warehousePrices'){form.value.product='';lookup('products')}},{flush:'sync'});watch(financeRevision,()=>{opened.value=false;load()});onMounted(()=>{load();lookup('clients');if(auth.hasPermi('warehouse:warehouses:list'))lookup('warehouses')})
</script>
<style scoped>.mb16{margin-bottom:16px}h3{font-size:16px}.tier-row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}</style>


